    $visible=ccrg_release('publish','Visible QA release',$a);$draft=ccrg_release('draft','PRIVATE_DRAFT_QA',$a);ccrg_release('private','PRIVATE_ENTRY_QA',$a);ccrg_release('future','FUTURE_ENTRY_QA',$a);ccrg_release('publish','PASSWORD_ENTRY_QA',$a,'1.2.3','secret-test');ccrg_release('publish','INVALID_VERSION_QA',$a,'<script>');
    $executed=false;add_shortcode('ccrg_test_execution',static function()use(&$executed){$executed=true;return'EXECUTED_BAD';});
    $html=Plugin::shortcode(['product'=>$slug,'limit'=>'10']);
