    ccrg_verify('Draft private future password and invalid details remain absent',!str_contains($html,'PRIVATE_')&&!str_contains($html,'FUTURE_ENTRY_QA')&&!str_contains($html,'PASSWORD_ENTRY_QA')&&!str_contains($html,'INVALID_VERSION_QA'));
    ccrg_verify('Body HTML is filtered and note shortcodes do not execute',!str_contains($html,'<script')&&!$executed&&str_contains($html,'[ccrg_test_execution]'));
    ccrg_verify('Unknown product returns no output',Plugin::shortcode(['product'=>'missing-qa-product'])==='');
    foreach([['limit'=>'0'],['limit'=>'51'],['limit'=>['10']],['product'=>'../draft'],['product'=>'bad<script>'],['limit'=>'10 ']]as$bad){ccrg_verify('Malformed shortcode attributes rejected',Plugin::shortcode($bad)==='');}
    ccrg_release('publish','Second visible QA release',$a);$bounded=Plugin::shortcode(['product'=>$slug,'limit'=>'1']);ccrg_verify('Result limit is honored',substr_count($bounded,'<article ')===1&&str_contains($bounded,'Second visible QA release'));
    $inject=static function($found,$query)use($draft){return$query->get('post_type')===Plugin::TYPE?[get_post($draft)]:$found;};add_filter('the_posts',$inject,10,2);ccrg_verify('Renderer repeats publish check after query filters',Plugin::shortcode(['product'=>$slug])==='');remove_filter('the_posts',$inject,10);
    foreach([[[] ,['new']],['1.0.0',['unknown']],['1.0.0',['new','new']],['1.0.0',['nested'=>['new']]],[' 1.0.0',['new']],['1.0.0',[]]]as[$version,$kinds]){ccrg_verify('Strict metadata rejects malformed types and enums',is_wp_error(Plugin::metadata($version,$kinds)));}
    ccrg_verify('Normal pre-release version supported',!is_wp_error(Plugin::metadata('2.0.0-beta.1',['improved'])));
    wp_set_current_user((int)$a);$_SERVER['REQUEST_METHOD']='POST';$_POST=['ccrg_nonce'=>wp_create_nonce('ccrg_meta_'.$visible),'ccrg_version'=>'2.0.0','ccrg_kinds'=>['improved']];Plugin::save($visible,get_post($visible));ccrg_verify('Author saves own metadata with action nonce',get_post_meta($visible,'_ccrg_version',true)==='2.0.0'&&get_post_meta($visible,'_ccrg_kinds',true)===['improved']);
    $prior=[get_post_meta($visible,'_ccrg_version',true),get_post_meta($visible,'_ccrg_kinds',true)];wp_set_current_user((int)$b);$_POST['ccrg_nonce']=wp_create_nonce('ccrg_meta_'.$visible);$_POST['ccrg_version']='9.0.0';Plugin::save($visible,get_post($visible));ccrg_verify('Different author cannot change another release metadata',get_post_meta($visible,'_ccrg_version',true)===$prior[0]);
    wp_set_current_user((int)$a);$_POST['ccrg_nonce']='bad';Plugin::save($visible,get_post($visible));ccrg_verify('Invalid plugin nonce preserves version',get_post_meta($visible,'_ccrg_version',true)===$prior[0]);
    $_POST['ccrg_nonce']=wp_create_nonce('ccrg_meta_'.$visible);$_SERVER['REQUEST_METHOD']='GET';Plugin::save($visible,get_post($visible));ccrg_verify('GET cannot change metadata',get_post_meta($visible,'_ccrg_version',true)===$prior[0]);
