    wp_set_current_user($owner->ID);ccrg_http('/wp-login.php');$login=ccrg_http('/wp-login.php','POST',['log'=>$credentials['user'],'pwd'=>$credentials['password'],'wp-submit'=>'Log In','testcookie'=>'1','redirect_to'=>$base.'/wp-admin/']);ccrg_verify('Real HTTP admin login',$login['status']===302);
