    $settings=ccrg_http('/wp-admin/options-general.php?page=ccrg-settings');$retention=ccrg_inputs($settings['body']);ccrg_verify('GET retention mutation denied',ccrg_http('/wp-admin/admin-post.php?action=ccrg_retention')['status']===403);$retention['remove_data']=['1'];ccrg_verify('Malformed retention checkbox is400 and unchanged',ccrg_http('/wp-admin/admin-post.php','POST',$retention)['status']===400&&get_option('ccrg_remove_data')===$before);$retention['remove_data']='1';ccrg_verify('Authorized retention opt-in saves',ccrg_http('/wp-admin/admin-post.php','POST',$retention)['status']===302&&(bool)get_option('ccrg_remove_data'));
